<template>
  <section class="purchase-panel">
    <header class="purchase-header"><div><h2>Mua hàng</h2><p>Đơn hàng và giao nhận từ CRM Joliefam</p></div><button :disabled="loading || !selected" @click="loadPurchase(true)">Cập nhật</button></header>
    <p v-if="!auth.canAccess('commerce')" class="notice">Anh chưa được cấp quyền xem thông tin mua hàng.</p>
    <template v-else-if="!effectiveContactId"><p>Chọn người liên hệ để xem hồ sơ mua hàng. Nhóm chat không được tự liên kết với khách.</p><form class="search" @submit.prevent="findContacts"><input v-model="contactQuery" placeholder="Tên hoặc điện thoại người liên hệ" aria-label="Tìm người liên hệ"><button>Tìm</button></form><button v-for="c in contactResults" :key="c.id" class="result" @click="chosenContact = c.id">{{ c.fullName || c.crmName || 'Khách hàng' }} · {{ c.phone }}</button></template>
    <template v-else>
      <p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="loading" class="muted">Đang tải thông tin mua hàng…</p>
      <template v-if="draftEditor"><OrderDraftEditor :key="draftEditor.id" :contact-id="effectiveContactId" :initial="draftEditor" :links="links" :customer="overview?.data.customer" @saved="onDraftSaved" @close="draftEditor = null" /></template>
      <template v-else-if="orderDetail"><OrderDetail :order="orderDetail.data" :updated-at="orderDetail.updatedAt" :stale="orderDetail.stale" @close="orderDetail = null" /></template>
      <template v-else>
        <label v-if="links.length">Hồ sơ đang xem<select v-model="selected"><option value="">Chọn khách / khách sạn</option><option v-for="l in links" :key="l.id" :value="l.customerId">{{ l.customerName }}</option></select></label>
        <div class="actions"><button v-if="auth.canAccess('commerce_link', 'access')" @click="linking = !linking">{{ linking ? 'Đóng liên kết' : links.length ? 'Quản lý liên kết' : 'Liên kết khách CRM' }}</button><button v-if="auth.canAccess('commerce_draft', 'create')" class="primary" :disabled="loading" @click="newDraft">+ Tạo đơn nháp</button><RouterLink v-if="compact" :to="`/contacts/${effectiveContactId}/profile?tab=purchases`">Xem đầy đủ ↗</RouterLink></div>
        <section v-if="linking || !links.length" class="link-section">
          <h3>Xác nhận đúng hồ sơ khách CRM</h3><p class="muted">Kiểm tra tên khách sạn, điện thoại và người liên hệ trước khi liên kết. Có thể gắn nhiều hồ sơ nếu khách làm cho nhiều khách sạn.</p>
          <template v-if="auth.canAccess('commerce_link', 'access')"><form class="search" @submit.prevent="findCustomers()"><input v-model="query" placeholder="Điện thoại, mã khách hoặc tên khách sạn" aria-label="Tìm hồ sơ CRM"><button :disabled="searching">Tìm</button></form><p v-if="searchError" role="alert" class="error">{{ searchError }}</p><p v-if="searched && !candidates.length">Chưa tìm thấy hồ sơ phù hợp.</p>
          <article v-for="c in candidates" :key="c.id" class="candidate"><b>{{ c.name }} · {{ c.code }}</b><p>{{ c.kind === 'hotel' ? 'Khách sạn' : 'Cá nhân' }} · {{ c.phone || 'Chưa có điện thoại' }}</p><select v-model="candidateContacts[c.id]" aria-label="Người liên hệ trong CRM"><option value="">Chưa xác định người liên hệ</option><option v-for="p in c.contacts" :key="p.id" :value="p.id">{{ p.name }} · {{ p.phone }}</option></select><label class="confirm"><input v-model="candidateConfirmed[c.id]" type="checkbox">Tôi đã kiểm tra đúng hồ sơ khách.</label><button :disabled="!candidateConfirmed[c.id] || linkingBusy || !auth.canAccess('commerce_link', 'edit')" @click="confirmLink(c)">Xác nhận liên kết</button></article><button v-if="candidateCursor" :disabled="searching" @click="findCustomers(candidateCursor)">Tải thêm khách</button></template>
          <details v-if="auth.canAccess('commerce_link', 'edit')"><summary>Khách mới chưa có trong CRM</summary><p>CRM sẽ kiểm tra trùng trước khi tạo. Nếu có kết quả trùng, tìm và chọn lại hồ sơ có sẵn.</p><label>Tên khách / khách sạn<input v-model="newCustomer.name" maxlength="200"></label><label>Điện thoại<input v-model="newCustomer.phone" maxlength="40"></label><label>Loại khách<select v-model="newCustomer.kind"><option value="hotel">Khách sạn</option><option value="individual">Cá nhân</option></select></label><button :disabled="linkingBusy || !newCustomer.name || !newCustomer.phone" @click="createCustomer">Tạo khách và liên kết</button></details>
          <article v-for="l in links" :key="l.id" class="linked"><span>{{ l.customerName }}</span><button v-if="auth.canAccess('commerce_link', 'edit')" @click="unlinkId = unlinkId === l.customerId ? '' : l.customerId">Gỡ liên kết</button><div v-if="unlinkId === l.customerId"><p>Gỡ liên kết với {{ l.customerName }}? Lịch sử đơn vẫn được giữ trong CRM.</p><button :disabled="linkingBusy" @click="unlink(l.customerId)">Xác nhận gỡ</button></div></article>
        </section>
        <template v-if="overview && selected">
          <section class="customer"><strong>{{ overview.data.customer.name }}</strong><span>{{ overview.data.customer.code }} · {{ overview.data.customer.phone }}</span><a v-if="safeLink(overview.data.customer.url)" :href="safeLink(overview.data.customer.url)" target="_blank" rel="noopener noreferrer">Mở hồ sơ CRM ↗</a></section>
          <p class="muted">Cập nhật lúc {{ dateTime(overview.updatedAt) }} <span v-if="overview.stale">· Bản lưu gần nhất</span></p><p v-if="overview.error || orders?.error" class="notice">{{ overview.error || orders?.error }}</p>
          <div class="stats"><div><span>Đơn chính thức</span><b>{{ overview.data.summary.orderCount ?? 'Chưa có thông tin' }}</b></div><div><span>Tiền hàng sau trả hàng</span><b>{{ money(overview.data.summary.netSales) }}</b></div><div><span>Đã thu</span><b>{{ money(overview.data.summary.collected) }}</b></div><div><span>Còn phải thu</span><b>{{ money(overview.data.summary.due) }}</b></div></div>
          <p>Đơn đang xử lý: <b>{{ overview.data.summary.activeOrderCount ?? 'Chưa có thông tin' }}</b></p>
          <details><summary>Người liên hệ và địa chỉ nhận hàng</summary><p v-for="c in overview.data.customer.contacts" :key="c.id">{{ c.name }} · {{ c.phone }}</p><p v-for="(a, i) in overview.data.customer.addresses" :key="i">{{ a.name }} · {{ a.phone }}<br>{{ a.address }}</p><p v-if="!overview.data.customer.addresses.length">Chưa có địa chỉ nhận hàng.</p></details>
        </template>
        <section v-if="selected" class="orders"><h3>Lịch sử đơn hàng</h3><form class="filters" @submit.prevent="applyFilter"><input v-model="orderQuery" placeholder="Tìm mã đơn" aria-label="Tìm mã đơn"><select v-model="orderStatus" aria-label="Lọc tình trạng đơn"><option value="">Tất cả tình trạng</option><option value="active">Đang xử lý</option><option value="pending_approval">Chờ duyệt</option><option value="production">Đang sản xuất</option><option value="shipping">Đang giao</option><option value="problem">Có vấn đề</option><option value="completed">Hoàn tất</option><option value="cancelled">Đã hủy</option></select><template v-if="!compact"><label>Từ ngày<input v-model="from" type="date"></label><label>Đến ngày<input v-model="to" type="date"></label></template><button>Lọc</button></form>
          <p v-if="orders && !orders.data.items.length" class="muted">Chưa có đơn phù hợp.</p><button v-for="o in orders?.data.items" :key="o.id" class="order-row" @click="openOrder(o.id)"><div><b>{{ o.code }}</b><strong>{{ money(o.total) }}</strong></div><p>Duyệt: {{ o.approval?.label || 'Chưa có thông tin' }} · Hàng: {{ o.processing?.label || 'Chưa có thông tin' }}</p><p>Tiền: {{ o.payment?.label || 'Chưa có thông tin' }} · Giao: {{ o.delivery?.label || 'Chưa có thông tin' }}</p></button><button v-if="orders?.data.nextCursor" :disabled="loading" @click="loadOrders(true, orders.data.nextCursor)">Tải thêm đơn</button>
        </section>
        <section v-if="auth.canAccess('commerce_draft')"><h3>Đơn nháp từ ZCRM</h3><p v-if="!drafts.length" class="muted">Chưa có đơn nháp.</p><button v-for="d in drafts" :key="d.id" class="draft-row" @click="draftEditor = d"><b>{{ d.crmOrderCode || `Nháp ${d.id.slice(0, 8)}` }}</b><span>{{ draftLabel(d.status) }} · {{ dateTime(d.updatedAt) }}</span></button><button v-if="draftCursor" @click="loadDrafts(draftCursor)">Tải thêm đơn nháp</button></section>
      </template>
    </template>
  </section>
</template>
<script setup lang="ts">
import { ref, reactive, computed, watch, onBeforeUnmount } from 'vue';
import { api } from '@/api';
import { useAuthStore } from '@/stores/auth';
import OrderDetail from './OrderDetail.vue';
import OrderDraftEditor from './OrderDraftEditor.vue';
import { commerceApi, purchaseError, money, dateTime, safeLink, type Link, type Customer, type Summary, type Snapshot, type Page, type Order, type OrderSummary, type Draft } from '@/api/commerce';
const props = defineProps<{ contactId?: string | null; compact?: boolean; requireContactSelection?: boolean }>();
const auth = useAuthStore(), chosenContact = ref('');
const effectiveContactId = computed(() => props.requireContactSelection ? chosenContact.value : props.contactId || chosenContact.value);
const links = ref<Link[]>([]), selected = ref(''), overview = ref<Snapshot<{ customer: Customer; summary: Summary }> | null>(null), orders = ref<Snapshot<Page<OrderSummary>> | null>(null), orderDetail = ref<Snapshot<Order> | null>(null), draftEditor = ref<Draft | null>(null);
const loading = ref(false), error = ref(''), linking = ref(false), query = ref(''), searching = ref(false), searched = ref(false), searchError = ref(''), candidates = ref<Customer[]>([]), candidateCursor = ref<string | null>(null), candidateContacts = reactive<Record<string, string>>({}), candidateConfirmed = reactive<Record<string, boolean>>({}), linkingBusy = ref(false), unlinkId = ref('');
const drafts = ref<Draft[]>([]), draftCursor = ref<string | null>(null), newCustomer = reactive({ name: '', phone: '', kind: 'hotel' as 'hotel' | 'individual' });
const orderQuery = ref(''), orderStatus = ref(''), from = ref(''), to = ref(''), appliedFilters = ref<Record<string, string>>({});
const contactQuery = ref(''), contactResults = ref<Array<{ id: string; fullName?: string; crmName?: string; phone?: string }>>([]);
let generation = 0, purchaseRequest = 0, orderRequest = 0, searchRequest = 0, timer: ReturnType<typeof setInterval> | undefined;
let customerCreateKey = crypto.randomUUID(), draftCreateKey = crypto.randomUUID();
const fresh = (g: number, id: string) => g === generation && id === effectiveContactId.value;
const draftLabel = (s: string) => ({ closed: 'Đã kết thúc trong CRM', local: 'Nháp tại ZCRM', returned: 'Cần bổ sung', submitting: 'Đang gửi', submitted: 'Đã gửi CRM', uncertain: 'Chưa xác nhận kết quả' }[s] || s);
watch(() => [props.contactId, props.requireContactSelection], () => { chosenContact.value = ''; });
watch(effectiveContactId, async id => {
  const g = ++generation; purchaseRequest++; orderRequest++; searchRequest++; clearInterval(timer);
  links.value = []; selected.value = ''; overview.value = null; orders.value = null; orderDetail.value = null; drafts.value = []; draftEditor.value = null; error.value = ''; candidates.value = []; searched.value = false; linking.value = false; query.value = ''; candidateCursor.value = null; draftCursor.value = null; orderQuery.value = ''; orderStatus.value = ''; from.value = ''; to.value = ''; appliedFilters.value = {}; linkingBusy.value = false; searching.value = false; searchError.value = ''; unlinkId.value = ''; customerCreateKey = crypto.randomUUID(); draftCreateKey = crypto.randomUUID(); newCustomer.name = ''; newCustomer.phone = ''; newCustomer.kind = 'hotel';
  if (!id || !auth.canAccess('commerce')) { loading.value = false; return; }
  loading.value = true;
  try { const list = await commerceApi.links(id); if (!fresh(g, id)) return; links.value = list; selected.value = list.length === 1 ? list[0]!.customerId : ''; await loadDrafts(); }
  catch (e) { if (fresh(g, id)) error.value = purchaseError(e); }
  finally { if (fresh(g, id)) loading.value = false; }
  timer = setInterval(() => { if (document.visibilityState !== 'hidden') void loadPurchase(true); }, 60000);
}, { immediate: true });
watch(selected, () => { overview.value = null; orders.value = null; orderDetail.value = null; appliedFilters.value = {}; orderQuery.value = ''; orderStatus.value = ''; from.value = ''; to.value = ''; if (selected.value) void loadPurchase(); });
async function loadPurchase(refresh = false) {
  const id = effectiveContactId.value, customerId = selected.value, g = generation, request = ++purchaseRequest; if (!id || !customerId) return;
  loading.value = true; error.value = '';
  try { const result = await commerceApi.overview(id, customerId, refresh); if (!fresh(g, id) || customerId !== selected.value || request !== purchaseRequest) return; overview.value = result; await loadOrders(refresh); if (refresh) await loadDrafts(); if (orderDetail.value) await openOrder(orderDetail.value.data.id, refresh); if (!refresh) void loadPurchase(true); }
  catch (e) { if (fresh(g, id) && request === purchaseRequest) error.value = purchaseError(e); }
  finally { if (fresh(g, id) && request === purchaseRequest) loading.value = false; }
}
async function loadOrders(refresh: boolean, cursor = '') {
  const id = effectiveContactId.value, customerId = selected.value, g = generation, request = ++orderRequest; if (!id || !customerId) return;
  try { const result = await commerceApi.orders(id, customerId, { ...appliedFilters.value, cursor, refresh }); if (!fresh(g, id) || customerId !== selected.value || request !== orderRequest) return; if (cursor && orders.value) result.data.items = [...orders.value.data.items, ...result.data.items]; orders.value = result; }
  catch (e) { if (fresh(g, id) && request === orderRequest) error.value = purchaseError(e); }
}
function applyFilter() { appliedFilters.value = { q: orderQuery.value, status: orderStatus.value, from: from.value, to: to.value }; void loadOrders(true); }
let detailRequest = 0;
async function openOrder(orderId: string, refresh = false) { const id = effectiveContactId.value, c = selected.value, g = generation, request = ++detailRequest; if (!id) return; try { const result = await commerceApi.order(id, c, orderId, refresh); if (fresh(g, id) && c === selected.value && request === detailRequest) { orderDetail.value = result; if (!refresh) void openOrder(orderId, true); } } catch (e) { if (fresh(g, id) && request === detailRequest) error.value = purchaseError(e); } }
async function findCustomers(cursor = '') { const id = effectiveContactId.value, g = generation, request = ++searchRequest; if (!id) return; searching.value = true; searchError.value = ''; try { const result = await commerceApi.search(id, query.value, cursor); if (fresh(g, id) && request === searchRequest) { candidates.value = cursor ? [...candidates.value, ...result.items] : result.items; candidateCursor.value = result.nextCursor; searched.value = true; } } catch (e) { if (fresh(g, id) && request === searchRequest) searchError.value = purchaseError(e); } finally { if (fresh(g, id) && request === searchRequest) searching.value = false; } }
async function confirmLink(c: Customer) { const id = effectiveContactId.value, g = generation; if (!id || !candidateConfirmed[c.id]) return; linkingBusy.value = true; error.value = ''; try { await commerceApi.link(id, { customerId: c.id, crmContactId: candidateContacts[c.id], confirmed: true }); const list = await commerceApi.links(id); if (fresh(g, id)) { links.value = list; selected.value = c.id; linking.value = false; } } catch (e) { if (fresh(g, id)) error.value = purchaseError(e); } finally { if (fresh(g, id)) linkingBusy.value = false; } }
async function unlink(customerId: string) { const id = effectiveContactId.value, g = generation; if (!id) return; linkingBusy.value = true; try { await commerceApi.unlink(id, customerId); const list = await commerceApi.links(id); if (fresh(g, id)) { links.value = list; if (selected.value === customerId) selected.value = ''; unlinkId.value = ''; } } catch (e) { if (fresh(g, id)) error.value = purchaseError(e); } finally { if (fresh(g, id)) linkingBusy.value = false; } }
async function createCustomer() { const id = effectiveContactId.value, g = generation; if (!id) return; linkingBusy.value = true; error.value = ''; try { const result = await commerceApi.createCustomer(id, { ...newCustomer, requestKey: customerCreateKey }); const list = await commerceApi.links(id); if (fresh(g, id)) { links.value = list; selected.value = result.customerId; customerCreateKey = crypto.randomUUID(); } } catch (e) { if (fresh(g, id)) error.value = purchaseError(e); } finally { if (fresh(g, id)) linkingBusy.value = false; } }
async function loadDrafts(cursor = '') { const id = effectiveContactId.value, g = generation; if (!id || !auth.canAccess('commerce_draft')) return; try { const result = await commerceApi.drafts(id, cursor); if (fresh(g, id)) { drafts.value = cursor ? [...drafts.value, ...result.items] : result.items; draftCursor.value = result.nextCursor; if (draftEditor.value) { const latest = result.items.find(d => d.id === draftEditor.value?.id); if (latest) draftEditor.value = latest; } } } catch (e) { if (fresh(g, id)) error.value = purchaseError(e); } }
async function newDraft() { const id = effectiveContactId.value, g = generation; if (!id) return; loading.value = true; error.value = ''; try { const result = await commerceApi.save(id, { createKey: draftCreateKey, input: { customerId: selected.value || null, orderedBy: '', recipient: { name: '', phone: '', address: '' }, desiredDate: '', notes: '', lines: [] } }); if (fresh(g, id)) { draftEditor.value = result; draftCreateKey = crypto.randomUUID(); onDraftSaved(result); } } catch (e) { if (fresh(g, id)) error.value = purchaseError(e); } finally { if (fresh(g, id)) loading.value = false; } }
function onDraftSaved(d: Draft) { if (d.contactId !== effectiveContactId.value) return; const i = drafts.value.findIndex(v => v.id === d.id); if (i >= 0) drafts.value[i] = d; else drafts.value.unshift(d); }
async function findContacts() { const g = generation; try { const { data } = await api.get('/contacts', { params: { search: contactQuery.value, limit: 20 } }); if (g === generation) contactResults.value = data.contacts || []; } catch (e) { error.value = purchaseError(e); } }
onBeforeUnmount(() => { generation++; clearInterval(timer); });
</script>
<style scoped>
